#[test]
fn exact_value() {
    assert_eq!(arboresce_xtask::value(), 1);
    let context = std::path::PathBuf::from(std::env::var_os("ARBORESCE_NATIVE_CONTEXT").unwrap());
    let output = context.parent().unwrap();
    let raw = output.join("raw");
    let completed = std::fs::read_dir(context.join("exits"))
        .unwrap()
        .map(|entry| {
            let path = entry.unwrap().path();
            path.file_stem()
                .unwrap()
                .to_str()
                .unwrap()
                .parse::<u32>()
                .unwrap()
        })
        .collect::<std::collections::BTreeSet<_>>();
    let pattern = std::env::var("LLVM_PROFILE_FILE").unwrap();
    let filename = std::path::Path::new(&pattern)
        .file_name()
        .unwrap()
        .to_str()
        .unwrap();
    let stem = filename.strip_suffix("%p-%12m.profraw").unwrap();
    let mut paths = std::fs::read_dir(&raw)
        .unwrap()
        .map(|entry| entry.unwrap().path())
        .collect::<Vec<_>>();
    paths.sort();
    let mut candidates = Vec::new();
    for path in paths {
        let name = path.file_name().unwrap().to_str().unwrap();
        let Some(suffix) = name.strip_prefix(stem) else {
            continue;
        };
        let pid = suffix.split('-').next().unwrap().parse::<u32>().unwrap();
        if pid == std::process::id() || !completed.contains(&pid) {
            continue;
        }
        let bytes = std::fs::read(&path).unwrap();
        if bytes.len() < 152 || bytes.len() > 67108864 {
            continue;
        }
        let word =
            |index: usize| u64::from_le_bytes(bytes[index * 8..index * 8 + 8].try_into().unwrap());
        if word(0) != 0xff6c70726f667281
            || word(1) != 11
            || [2, 4, 6, 7, 8, 9, 10, 11, 16, 17]
                .iter()
                .any(|i| word(*i) != 0)
        {
            continue;
        }
        let counters = word(5);
        let names = word(12);
        let records = word(3);
        if records > 4096 || counters > 65536 || names == 0 || names > 8388608 {
            continue;
        }
        let complete = 152 + records * 72 + counters * 8 + names + (8 - names % 8) % 8;
        if complete != bytes.len() as u64 {
            continue;
        }
        let count = u64::from_le_bytes(bytes[24..32].try_into().unwrap());
        if count > 0 {
            candidates.push((path, bytes));
        }
    }
    let (target, before) = &candidates[0];
    let (replacement_path, replacement) = candidates
        .iter()
        .skip(1)
        .find(|(_, bytes)| bytes[152..168] != before[152..168])
        .unwrap();
    let proof = output.join("profile-substitution");
    std::fs::create_dir(&proof).unwrap();
    std::fs::write(proof.join("target-path"), target.to_str().unwrap()).unwrap();
    std::fs::write(
        proof.join("replacement-path"),
        replacement_path.to_str().unwrap(),
    )
    .unwrap();
    std::fs::write(proof.join("before.profraw"), before).unwrap();
    std::fs::write(proof.join("replacement.profraw"), replacement).unwrap();
    std::fs::write(target, replacement).unwrap();
    println!("Collector profile substitution witness.");
}

